const raw =
  $json.output ??
  $json.text ??
  $json.response ??
  '';

const marker = 'FINAL_RESPONSE:';

const index = raw.lastIndexOf(marker);

const cleanText =
  index >= 0
    ? raw.slice(index + marker.length).trim()
    : raw.trim();

return {
  json: {
    ...$json,
    clean_text: cleanText
  }
};
